#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 1000000007
#define MAXN 200005

typedef long long ll;

typedef struct {
    int a, b;
} Pair;

Pair norm[MAXN];
int zero_cnt = 0;
int n;

int gcd(int x, int y) {
    while (y) {
        int t = y;
        y = x % y;
        x = t;
    }
    return x;
}

void normalize(int a, int b, int* na, int* nb) {
    if (a == 0 && b == 0) {
        *na = 0; *nb = 0;
        return;
    }
    int g = gcd(abs(a), abs(b));
    a /= g;
    b /= g;
    // canonical sign: make first non-zero component positive
    if (a < 0 || (a == 0 && b < 0)) {
        a = -a;
        b = -b;
    }
    *na = a;
    *nb = b;
}

int cmp(const void* x, const void* y) {
    Pair* p = (Pair*)x;
    Pair* q = (Pair*)y;
    if (p->a != q->a) return p->a - q->a;
    return p->b - q->b;
}

ll mod_pow(ll base, int exp) {
    ll res = 1;
    while (exp) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

int main() {
    scanf("%d", &n);
    int m = 0;
    for (int i = 0; i < n; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        if (a == 0 && b == 0) {
            zero_cnt++;
        } else {
            int na, nb;
            normalize(a, b, &na, &nb);
            norm[m].a = na;
            norm[m].b = nb;
            m++;
        }
    }

    qsort(norm, m, sizeof(Pair), cmp);

    // Count frequencies of each direction
    int freq[MAXN];
    int dirs = 0;
    int idx = 0;
    while (idx < m) {
        int j = idx;
        while (j < m && norm[j].a == norm[idx].a && norm[j].b == norm[idx].b) j++;
        freq[dirs] = j - idx;
        norm[dirs] = norm[idx]; // keep the direction
        dirs++;
        idx = j;
    }

    // Mark used directions
    int used[dirs];
    memset(used, 0, sizeof(used));

    ll ans = 1;
    for (int i = 0; i < dirs; i++) {
        if (used[i]) continue;
        int a = norm[i].a;
        int b = norm[i].b;
        // Find orthogonal direction
        int oa, ob;
        normalize(-b, a, &oa, &ob);
        int j = -1;
        // binary search for oa,ob
        int lo = 0, hi = dirs-1;
        while (lo <= hi) {
            int mid = (lo+hi)/2;
            if (norm[mid].a < oa || (norm[mid].a == oa && norm[mid].b < ob)) lo = mid+1;
            else if (norm[mid].a > oa || (norm[mid].a == oa && norm[mid].b > ob)) hi = mid-1;
            else { j = mid; break; }
        }
        ll cnt1 = freq[i];
        ll cnt2 = 0;
        if (j != -1 && !used[j]) {
            cnt2 = freq[j];
            used[j] = 1;
        }
        // ways for this pair: (2^cnt1 + 2^cnt2 - 1)
        ll ways = (mod_pow(2, cnt1) + mod_pow(2, cnt2) - 1) % MOD;
        if (ways < 0) ways += MOD;
        ans = (ans * ways) % MOD;
        used[i] = 1;
    }

    // handle zero vectors
    ans = (ans * mod_pow(2, zero_cnt)) % MOD;

    // subtract empty set
    ans = (ans - 1 + MOD) % MOD;

    printf("%lld\n", ans);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

typedef long long ll;

typedef struct {
    ll x, y;
} Pair;

static ll gcdll(ll a, ll b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b) {
        ll t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static int cmp_pair(const void *a, const void *b) {
    Pair *p = (Pair *)a;
    Pair *q = (Pair *)b;
    if (p->x != q->x) return (p->x < q->x) ? -1 : 1;
    if (p->y != q->y) return (p->y < q->y) ? -1 : 1;
    return 0;
}

static ll modpow(ll a, ll e) {
    ll r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Pair *arr = (Pair *)malloc(sizeof(Pair) * N);
    int m = 0;
    ll zero_cnt = 0;

    for (int i = 0; i < N; i++) {
        ll a, b;
        scanf("%lld %lld", &a, &b);

        if (a == 0 && b == 0) {
            zero_cnt++;
            continue;
        }

        ll g = gcdll(a, b);
        a /= g;
        b /= g;

        /* Normalize direction:
           make representative unique by:
           - if a < 0, multiply by -1
           - if a == 0, make b > 0
        */
        if (a < 0 || (a == 0 && b < 0)) {
            a = -a;
            b = -b;
        }

        arr[m].x = a;
        arr[m].y = b;
        m++;
    }

    qsort(arr, m, sizeof(Pair), cmp_pair);

    Pair *keys = (Pair *)malloc(sizeof(Pair) * m);
    ll *cnt = (ll *)malloc(sizeof(ll) * m);
    int K = 0;

    for (int i = 0; i < m; ) {
        int j = i + 1;
        while (j < m && arr[j].x == arr[i].x && arr[j].y == arr[i].y) j++;
        keys[K] = arr[i];
        cnt[K] = j - i;
        K++;
        i = j;
    }

    char *used = (char *)calloc(K, sizeof(char));

    ll ans = 1;

    for (int i = 0; i < K; i++) {
        if (used[i]) continue;

        ll a = keys[i].x, b = keys[i].y;

        /* Perpendicular normalized partner:
           (a,b) -> (-b,a), then normalize */
        ll c = -b, d = a;
        if (c < 0 || (c == 0 && d < 0)) {
            c = -c;
            d = -d;
        }

        /* binary search partner */
        int l = 0, r = K - 1, pos = -1;
        while (l <= r) {
            int mid = (l + r) >> 1;
            if (keys[mid].x < c || (keys[mid].x == c && keys[mid].y < d)) {
                l = mid + 1;
            } else if (keys[mid].x > c || (keys[mid].x == c && keys[mid].y > d)) {
                r = mid - 1;
            } else {
                pos = mid;
                break;
            }
        }

        if (pos == -1) {
            ans = ans * modpow(2, cnt[i]) % MOD;
            used[i] = 1;
        } else {
            if (used[pos]) continue;
            ll waysA = modpow(2, cnt[i]);
            ll waysB = modpow(2, cnt[pos]);
            ans = ans * ((waysA + waysB - 1 + MOD) % MOD) % MOD;
            used[i] = 1;
            used[pos] = 1;
        }
    }

    ans = (ans + zero_cnt - 1) % MOD;
    if (ans < 0) ans += MOD;

    printf("%lld\n", ans);

    free(arr);
    free(keys);
    free(cnt);
    free(used);
    return 0;
}

