        long long g = std::gcd(std::llabs(A), std::llabs(B));
        A /= g;
        B /= g;

        // Normalize direction:
        // make B > 0, or if B == 0 then A > 0
        if (B < 0 || (B == 0 && A < 0)) {
            A = -A;
            B = -B;
        }

        cnt[{A, B}]++;
    }

    set<pair<long long,long long>> used;
