        if (ways < 0) ways += MOD;

        ans = ans * ways % MOD;

        used.insert(p);
        used.insert(q);
    }

    // Exclude empty set from non-zero vectors, then add choices with one zero vector.
    ans = (ans - 1 + MOD) % MOD;
    ans = (ans + zeroCnt) % MOD;

    cout << ans % MOD << '\n';
    return 0;
}

