public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        Map<String, Integer> countMap = new HashMap<>();
        int zeroCount = 0;

        for (int i = 0; i < n; i++) {
            long a = sc.nextLong();
            long b = sc.nextLong();
            if (a == 0 && b == 0) {
                zeroCount++;
                continue;
            }
            long g = gcd(Math.abs(a), Math.abs(b));
            a /= g;
            b /= g;
            // canonical form: make first non-zero positive
            if (a < 0 || (a == 0 && b < 0)) {
                a = -a;
                b = -b;
            }
            String key = a + "," + b;
            countMap.put(key, countMap.getOrDefault(key, 0) + 1);
        }

        // Precompute powers of 2
        long[] pow2 = new long[n + 1];
        pow2[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow2[i] = (pow2[i-1] * 2) % MOD;
        }

        Set<String> used = new HashSet<>();
        long ans = 1;

        for (String key : countMap.keySet()) {
            if (used.contains(key)) continue;
            String[] parts = key.split(",");
            long a = Long.parseLong(parts[0]);
            long b = Long.parseLong(parts[1]);
            // perpendicular direction: (-b, a) normalized
            long na = -b;
            long nb = a;
            long g = gcd(Math.abs(na), Math.abs(nb));
            na /= g;
            nb /= g;
            if (na < 0 || (na == 0 && nb < 0)) {
                na = -na;
                nb = -nb;
            }
            String perpKey = na + "," + nb;

            int cnt1 = countMap.getOrDefault(key, 0);
            int cnt2 = countMap.getOrDefault(perpKey, 0);

            used.add(key);
            used.add(perpKey);

            long ways = (pow2[cnt1] + pow2[cnt2] - 1 + MOD) % MOD;
            ans = (ans * ways) % MOD;
        }

        // handle zeroCount: either take none from zeros, or any non-empty subset
        // but cannot combine zeros with any other
        ans = (ans * (pow2[zeroCount])) % MOD;

        // subtract the case where we pick nothing at all
        ans = (ans - 1 + MOD) % MOD;

        System.out.println(ans);
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}

