public class Main {
    static final long MOD = 1000000007;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());

        int zeroCount = 0;
        Map<String, Long> dirCount = new HashMap<>();

        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            long a = Long.parseLong(st.nextToken());
            long b = Long.parseLong(st.nextToken());
            if (a == 0 && b == 0) { zeroCount++; continue; }
            long g = gcd(Math.abs(a), Math.abs(b));
            a /= g; b /= g;
            // normalize sign: make first nonzero positive
            if (a < 0 || (a == 0 && b < 0)) { a = -a; b = -b; }
            String key = a + "," + b;
            dirCount.merge(key, 1L, Long::sum);
        }

        Set<String> visited = new HashSet<>();
        long result = 1;

        for (Map.Entry<String, Long> e : dirCount.entrySet()) {
            String key = e.getKey();
            if (visited.contains(key)) continue;
            visited.add(key);
            String[] parts = key.split(",");
            long a = Long.parseLong(parts[0]), b = Long.parseLong(parts[1]);
            // perpendicular direction: (-b, a) normalized
            long pa = -b, pb = a;
            long g = gcd(Math.abs(pa), Math.abs(pb));
            pa /= g; pb /= g;
            if (pa < 0 || (pa == 0 && pb < 0)) { pa = -pa; pb = -pb; }
            String perpKey = pa + "," + pb;
            long s1 = e.getValue();
            if (dirCount.containsKey(perpKey) && !visited.contains(perpKey)) {
                visited.add(perpKey);
                long s2 = dirCount.get(perpKey);
                result = result % MOD * ((pow2(s1) + pow2(s2) - 1 + MOD) % MOD) % MOD;
            } else {
                result = result % MOD * pow2(s1) % MOD;
            }
        }
        result = (result - 1 + MOD) % MOD;
        result = (result + zeroCount) % MOD;
        System.out.println(result);
    }

    static long pow2(long n) {
        long res = 1, base = 2; n %= (MOD-1);
        while (n > 0) { if ((n&1)==1) res=res*base%MOD; base=base*base%MOD; n>>=1; }
        return res;
    }
    static long gcd(long a, long b) { return b==0?a:gcd(b,a%b); }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static long gcd(long a, long b) {
        a = Math.abs(a);
        b = Math.abs(b);
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    static class Pair {
        long x, y;
        Pair(long x, long y) {
            this.x = x;
            this.y = y;
        }
        @Override
        public boolean equals(Object o) {
            if (!(o instanceof Pair)) return false;
            Pair p = (Pair) o;
            return x == p.x && y == p.y;
        }
        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();

        HashMap<Pair, Integer> cnt = new HashMap<>();
        long zeroCount = 0;

        for (int i = 0; i < N; i++) {
            long a = fs.nextLong();
            long b = fs.nextLong();

            if (a == 0 && b == 0) {
                zeroCount++;
                continue;
            }

            long g = gcd(a, b);
            a /= g;
            b /= g;

            // Normalize direction so each line through origin has unique representative
            if (b < 0 || (b == 0 && a < 0)) {
                a = -a;
                b = -b;
            }

            Pair key = new Pair(a, b);
            cnt.put(key, cnt.getOrDefault(key, 0) + 1);
        }

        HashSet<Pair> used = new HashSet<>();
        long ans = 1;

        for (Map.Entry<Pair, Integer> e : cnt.entrySet()) {
            Pair p = e.getKey();
            if (used.contains(p)) continue;

            long a = p.x, b = p.y;

            // Perpendicular normalized partner:
            // (a,b) -> (-b,a), then normalize by same rule
            long c = -b, d = a;
            if (d < 0 || (d == 0 && c < 0)) {
                c = -c;
                d = -d;
            }
            Pair q = new Pair(c, d);

            int s = cnt.getOrDefault(p, 0);
            int t = cnt.getOrDefault(q, 0);

            long ways = (modPow(2, s) + modPow(2, t) - 1 + MOD) % MOD;
            ans = ans * ways % MOD;

            used.add(p);
            used.add(q);
        }

        // Exclude empty set among non-zero vectors, then add one zero vector or none.
        ans = (ans - 1 + MOD) % MOD;
        ans = (ans + zeroCount) % MOD;

        System.out.println(ans);
    }
}
